"""Migration of the Meridian CRM 4.2 nightly case-escalation job."""

from datetime import date


_EVENT_WORKFLOW = "case_lifecycle"
_EVENT_NAME = "auto_escalate"
_NULL_DATE = "00000000"


def _parse_date(value: str) -> date:
    """Parse a legacy YYYYMMDD date."""
    if not isinstance(value, str) or len(value) != 8 or not value.isdigit():
        raise ValueError(f"invalid YYYYMMDD date: {value!r}")
    return date(int(value[0:4]), int(value[4:6]), int(value[6:8]))


def _datediff(first: str | None, second: str | None) -> int:
    """Return whole calendar days first - second using legacy null semantics."""
    if not first or not second or first == _NULL_DATE or second == _NULL_DATE:
        return 0
    return (_parse_date(first) - _parse_date(second)).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation events for overdue live cases."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: row.get("CASE_ID", "")):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        open_date = case.get("OPEN_DT", "")
        age_days = _datediff(today, open_date)

        overdue = (
            status == "N" and age_days >= 2
        ) or (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and age_days >= 7
        )

        if overdue:
            events.append(
                {
                    "workflow": _EVENT_WORKFLOW,
                    "entity_id": case.get("CASE_ID", ""),
                    "event": _EVENT_NAME,
                }
            )

    return events
